function parseQty(text) {
  const qty = Number(text);

  if (Number.isNaN(qty)) {
    throw new Error("bad quantity");
  }

  return qty;
}

let total = 0;

for (const text of ["2", "x", "5"]) {
  try {
    total += parseQty(text);
    console.log("added " + text);
  } catch (error) {
    console.log(error.message);
  }
}

console.log(total);
